"""관심목록 공통 화면과 동작. 마이페이지 홈 및 기존 렌더러에서 공유합니다."""

CONTENT = '<section class="panel"><div class="list-tools"><div class="filters" role="group" aria-label="관심 정보 종류"><button class="filter active" data-type="" aria-pressed="true">전체 <span id="count-all">0</span></button><button class="filter" data-type="job" aria-pressed="false">채용공고 <span id="count-job">0</span></button><button class="filter" data-type="course" aria-pressed="false">교육과정 <span id="count-course">0</span></button></div><form id="search-form" class="search"><label class="sr-only" for="search">저장한 정보 검색</label><input id="search" type="search" maxlength="100" placeholder="제목, 회사 또는 교육기관 검색"><button class="button" type="submit">검색</button></form></div><p id="list-status" class="muted" role="status" aria-live="polite">저장한 정보를 불러오는 중이에요.</p><div id="bookmark-list" class="bookmark-list"></div><div id="list-empty" class="bookmark-empty hidden"><span>♡</span><h2>저장한 정보가 없어요</h2><p id="empty-description">메인 화면에서 관심 있는 공고와 교육을 저장해 보세요.</p><a class="button primary" href="/main">메인으로 이동 →</a></div><button id="bookmark-retry" class="button hidden" type="button">다시 불러오기</button><div id="pagination" class="pagination hidden"><button class="button" id="previous" type="button">이전</button><span id="page-info"></span><button class="button" id="next" type="button">다음</button></div></section>'

SCRIPT = "(()=>{\n let type='',currentPage=1,query='',total=0,version=0;const size=10;\n const list=document.getElementById('bookmark-list'),status=document.getElementById('list-status'),empty=document.getElementById('list-empty'),retry=document.getElementById('bookmark-retry'),pagination=document.getElementById('pagination');\n function text(tag,value,className){const node=document.createElement(tag);node.textContent=value;if(className)node.className=className;return node;}\n function date(value){return new Date(value).toLocaleDateString('ko-KR');}\n function card(item){const node=document.createElement('article');node.className='bookmark-card';node.append(text('span',item.item_type==='job'?'채용공고':'교육모음',item.item_type==='job'?'badge badge-job':'badge badge-course'),text('h2',item.title),text('p',item.organization));\n  const details=[];if(item.location)details.push(item.location);if(item.item_type==='course'){if(item.cost!==null)details.push(item.cost===0?'무료':item.cost.toLocaleString()+'원');if(item.is_online!==null)details.push(item.is_online?'온라인':'오프라인');}if(details.length)node.append(text('p',details.join(' · ')));\n  node.append(text('p',item.deadline?'마감일: '+date(item.deadline):'마감일: 확인 필요'),text('p','저장일: '+date(item.created_at)));\n  const actions=document.createElement('div');actions.className='card-actions';const link=text('a','원문 보기 ↗','button');link.href=item.original_url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',item.title+' 원문 보기 (새 창)');\n  const remove=text('button','저장 취소','button remove');remove.type='button';remove.setAttribute('aria-label',item.title+' 저장 취소');remove.addEventListener('click',async()=>{if(!confirm('이 항목의 저장을 취소할까요?'))return;remove.disabled=true;try{await api('/api/bookmarks/'+item.id,{method:'DELETE'});document.getElementById('flash').textContent='저장을 취소했습니다.';await load();}catch(error){document.getElementById('flash').textContent=error.message;remove.disabled=false;}});actions.append(link,remove);node.append(actions);return node;\n }\n async function load(){const requestVersion=++version;status.textContent='저장한 정보를 불러오는 중이에요.';status.className='muted';retry.classList.add('hidden');empty.classList.add('hidden');pagination.classList.add('hidden');list.replaceChildren();const params=new URLSearchParams({page:currentPage,size});if(type)params.set('item_type',type);if(query)params.set('q',query);\n  try{const data=await api('/api/bookmarks?'+params);if(requestVersion!==version)return;total=data.total;window.dispatchEvent(new CustomEvent('bookmarks-loaded',{detail:data.counts}));const pages=Math.max(1,Math.ceil(total/size));if(currentPage>pages){currentPage=pages;return load();}for(const key of ['all','job','course'])document.getElementById('count-'+key).textContent=data.counts[key];status.textContent=`총 ${total}개의 정보를 찾았어요.`;data.items.forEach(item=>list.append(card(item)));empty.classList.toggle('hidden',total>0);document.getElementById('empty-description').textContent=query?'검색 조건을 바꾸어 다시 찾아보세요.':'메인 화면에서 관심 있는 공고와 교육을 저장해 보세요.';pagination.classList.toggle('hidden',pages<=1);document.getElementById('page-info').textContent=currentPage+' / '+pages;document.getElementById('previous').disabled=currentPage===1;document.getElementById('next').disabled=currentPage===pages;\n  }catch(error){if(requestVersion!==version)return;status.textContent=error.message;status.className='error';retry.classList.remove('hidden');}\n }\n document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{type=button.dataset.type;currentPage=1;document.querySelectorAll('.filter').forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button));});load();}));\n document.getElementById('search-form').addEventListener('submit',event=>{event.preventDefault();query=document.getElementById('search').value.trim();currentPage=1;load();});document.getElementById('previous').addEventListener('click',()=>{currentPage--;load();});document.getElementById('next').addEventListener('click',()=>{currentPage++;load();});retry.addEventListener('click',load);load();\n\n})();"

CSS = '.list-tools{display:flex;flex-wrap:wrap;gap:18px;justify-content:space-between;align-items:center;margin-top:24px}.filters{display:flex;gap:5px;flex-wrap:wrap}.filter{padding:10px 12px;background:white;border:1px solid transparent;border-radius:8px;font-size:12px;color:var(--muted)}.filter.active{background:#fff2c4;color:var(--ink);border-color:#f1df9c}.filter span{margin-left:4px;font-size:11px}.search{display:flex;gap:8px;width:100%}.search input{flex:1;min-width:0;width:auto}.bookmark-list{display:grid;gap:14px;margin-top:20px}.bookmark-card{border:1px solid var(--line);border-radius:13px;padding:21px}.bookmark-card h2{font-size:16px;margin:12px 0 6px;overflow-wrap:anywhere}.bookmark-card p{font-size:12px;margin:6px 0;color:var(--muted)}.badge{display:inline-block;font-size:10px;padding:6px 10px;background:#fff9e5;border:1px solid #e9ddb0;border-radius:20px;color:#7f7449}.card-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:16px;flex-wrap:wrap}.remove{color:#8f5946}.bookmark-empty{text-align:center;padding:36px 12px}.bookmark-empty>span{display:block;font-size:36px;color:#bca76a}.bookmark-empty h2{font-size:18px}.bookmark-empty p,.muted{color:var(--muted);font-size:12px;line-height:1.8}.bookmark-empty .button{margin-top:12px}.pagination{display:flex;align-items:center;justify-content:center;gap:16px;margin-top:24px;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}'

CSS += '\n.bookmark-card .badge-job{background:#e8f1ff;border-color:#c9daf7;color:#305d99}.bookmark-card .badge-course{background:#fff0df;border-color:#f0d2b1;color:#8e5424}\n'
